import json, sys
from transformers.models.auto.modeling_auto import MODEL_FOR_CAUSAL_LM_MAPPING_NAMES as M
IN_SCOPE = set("apertus arcee bitnet bloom cohere cohere2 ctrl cwm diffllama ernie4_5 exaone4 falcon falcon_h1 falcon_mamba gemma gemma2 gemma3_text glm glm4 gpt-sw3 gpt2 gpt_bigcode gpt_neo gpt_neox gpt_neox_japanese granite granite_swa helium hunyuan_v1_dense hyperclovax jais2 lfm2 llama mamba minicpm3 ministral ministral3 mistral modernbert-decoder moshi mpt nanochat olmo olmo2 olmo3 olmo_hybrid persimmon phi phi3 qwen2 qwen3 qwen3_5_text recurrent_gemma rwkv seed_oss smollm3 stablelm starcoder2 vaultgemma youtu".split())
ENCODERS = set("bert bert-generation camembert data2vec-text electra ernie megatron-bert rembert roberta roberta-prelayernorm xlm-roberta xlm-roberta-xl".split())
rows = {}
def walk(x):
    if isinstance(x, dict):
        t = x.get("model_type", x.get("type"))
        v = x.get("verdict", x.get("status"))
        if isinstance(t, str) and isinstance(v, str):
            rows.setdefault(t, set()).add(v.split()[0].strip(":").upper() if v.split() else "")
        for y in x.values():
            walk(y)
    elif isinstance(x, list):
        for y in x:
            walk(y)
walk(json.load(open(sys.argv[1])))
missing = sorted(set(M) - set(rows))
differ = sorted(t for t, v in rows.items() if "DIFFER" in v)
exact = {t for t, v in rows.items() if v == {"EXACT"}}
enc = sorted(exact & ENCODERS)
ins = len(exact & IN_SCOPE)
print(f"CENSUS rows={len(rows)} mapping={len(M)} EXACT={len(exact)} in_scope_EXACT={ins}/{len(IN_SCOPE)} DIFFER={len(differ)} encoders_admitted={len(enc)} missing={len(missing)}")
for name, bad in (("DIFFER", differ), ("encoder admitted", enc), ("type without a row", missing)):
    if bad:
        print(name + ": " + " ".join(bad))
sys.exit(1 if (differ or enc or missing or ins < 55) else 0)
